import networkx as nx
import numpy as np

def select_next_node(graph, unvisited_nodes):
    # Extract node features
    degree = {n: graph.nodes[n]['degree'] for n in unvisited_nodes}
    clustering = {n: graph.nodes[n]['clustering'] for n in unvisited_nodes}
    core_number = {n: graph.nodes[n]['core_number'] for n in unvisited_nodes}
    betweenness = {n: graph.nodes[n]['betweenness'] for n in unvisited_nodes}
    eigenvector = {n: graph.nodes[n]['eigenvector'] for n in unvisited_nodes}

    # Precompute percentiles for core_number
    core_vals = np.array(list(core_number.values()))
    core_percentiles = {n: np.searchsorted(np.sort(core_vals), core_number[n]) / len(core_vals) for n in unvisited_nodes}

    # Normalize closeness centrality (approximate by inverse shortest path length from precomputed avg path length info)
    # Since closeness not given, approximate by inverse distance to all nodes - skip and use eigenvector centrality as proxy for centrality
    # Instead, normalize eigenvector centrality and betweenness and degree
    eigen_vals = np.array(list(eigenvector.values()))
    eig_min, eig_max = eigen_vals.min(), eigen_vals.max()
    eig_norm = {n: (eigenvector[n] - eig_min) / (eig_max - eig_min) if eig_max > eig_min else 0 for n in unvisited_nodes}

    bet_vals = np.array(list(betweenness.values()))
    bet_min, bet_max = bet_vals.min(), bet_vals.max()
    bet_norm = {n: (betweenness[n] - bet_min) / (bet_max - bet_min) if bet_max > bet_min else 0 for n in unvisited_nodes}

    deg_vals = np.array(list(degree.values()))
    deg_min, deg_max = deg_vals.min(), deg_vals.max()
    deg_norm = {n: (degree[n] - deg_min) / (deg_max - deg_min) if deg_max > deg_min else 0 for n in unvisited_nodes}

    # Score calculation:
    # score = (normalized closeness + normalized eigenvector) * (core_number_percentile - clustering) * (degree / betweenness)
    # Since closeness not given, replace normalized closeness with normalized eigenvector again to emphasize centrality
    # Prevent division by zero in degree/betweenness by adding small epsilon

    eps = 1e-8
    scores = {}
    for n in unvisited_nodes:
        centrality_sum = eig_norm[n] + eig_norm[n]  # eigenvector used twice as proxy for closeness too
        core_clust_diff = core_percentiles[n] - clustering[n]
        ratio = (degree[n]) / (betweenness[n] + eps)
        scores[n] = centrality_sum * core_clust_diff * ratio

    # Select node with max score
    next_node = max(scores, key=scores.get)
    return next_node

import networkx as nx
import numpy as np

def select_next_node(graph, unvisited_nodes):
    # Precomputed global metrics
    max_core = graph.graph['precomputed']['max_core_k']
    max_betweenness = max(graph.nodes[n]['betweenness'] for n in graph.nodes)

    # Precompute closeness centrality only once for all nodes
    closeness_all = nx.closeness_centrality(graph)
    max_closeness = max(closeness_all.values())

    # Precompute local bridge score = edge betweenness on edges from node / degree or fallback 0
    # Here, we approximate local bridge score per node as max edge betweenness among edges incident to node, normalized
    edge_betweenness = nx.edge_betweenness_centrality(graph)

    def local_bridge_score(node):
        edges = graph.edges(node)
        if not edges:
            return 0
        scores = [edge_betweenness[e if e in edge_betweenness else (e[1], e[0])] for e in edges]
        return max(scores) if scores else 0

    max_local_bridge = 0
    local_bridge_dict = {}
    for n in graph.nodes:
        lb = local_bridge_score(n)
        local_bridge_dict[n] = lb
        if lb > max_local_bridge:
            max_local_bridge = lb
    if max_local_bridge == 0:
        max_local_bridge = 1  # avoid div 0

    # Precompute avg neighbor degree inverse normalized:
    avg_nb_degree_inv = {}
    max_avg_nb_inv = 0
    for n in graph.nodes:
        neighbors = list(graph.neighbors(n))
        if neighbors:
            avg_deg = np.mean([graph.nodes[nb]['degree'] for nb in neighbors])
            val = 1/avg_deg if avg_deg > 0 else 0
        else:
            val = 0
        avg_nb_degree_inv[n] = val
        if val > max_avg_nb_inv:
            max_avg_nb_inv = val
    if max_avg_nb_inv == 0:
        max_avg_nb_inv = 1

    # Normalize function helpers
    def norm(val, max_val):
        return val/max_val if max_val > 0 else 0

    def weighted_geometric_mean(a, b, w=0.5):
        a = max(a, 1e-9)
        b = max(b, 1e-9)
        return (a**w) * (b**(1-w))

    def logistic(x):
        return 1/(1 + np.exp(-x))

    def sigmoid(x):
        return 1/(1 + np.exp(-x))

    def decayed_log(x):
        return np.exp(-1/(x+1e-9))*np.log(x+1)

    scores = {}
    for n in unvisited_nodes:
        eig = norm(graph.nodes[n]['eigenvector'], 1)  # eigenvector normalized to [0,1]
        clos = norm(closeness_all[n], max_closeness)
        hg_mean = weighted_geometric_mean(eig, clos, w=0.6)

        inv_clust = 1 - graph.nodes[n]['clustering']  # inverse clustering coefficient
        lb_norm = norm(local_bridge_dict[n], max_local_bridge)
        pow_exp = logistic(inv_clust) * lb_norm

        core_norm = norm(graph.nodes[n]['core_number'], max_core)
        betw_norm = norm(graph.nodes[n]['betweenness'], max_betweenness)
        inv_avg_nb_norm = norm(avg_nb_degree_inv[n], max_avg_nb_inv)

        add_factor = decayed_log(core_norm) + sigmoid(betw_norm) * inv_avg_nb_norm

        score = (hg_mean ** pow_exp) * add_factor
        scores[n] = score

    next_node = max(scores, key=scores.get)
    return next_node
